<?php $editing = $item !== null; $errors = session()->getFlashdata('errors') ?? []; ?>
<div class="page-heading"><div><p class="eyebrow">Item management</p><h1><?= $editing ? 'Edit item' : 'Add item' ?></h1><p><?= $editing ? 'Update the item description and availability. Manage each price from its size variants.' : 'Create an item and define its size-specific prices in the same form. Maintain the storage item catalog from this page.' ?></p></div><div class="page-actions"><a class="btn btn-outline-secondary" href="<?= site_url('admin/items') ?>">Back to items</a><?php if ($editing): ?><a class="btn btn-outline-primary" href="<?= site_url('admin/items/' . $item['id'] . '/sizes') ?>">Manage sizes</a><?php endif ?></div></div>
