<div class="col-12"><label class="form-label" for="name">Item name</label><input class="form-control<?= isset($errors['name']) ? ' is-invalid' : '' ?>" id="name" name="name" value="<?= esc(old('name', $item['name'] ?? ''), 'attr') ?>" maxlength="120" required autofocus><?php if (isset($errors['name'])): ?><div class="invalid-feedback"><?= esc($errors['name']) ?></div><?php endif ?></div>
