<?php if (! $editing): ?><div class="col-12"><div class="d-flex justify-content-between align-items-center mb-2"><label class="form-label mb-0">Size variants and prices</label><button class="btn btn-sm btn-outline-primary" type="button" data-add-size-row>Add another size</button></div><p class="field-hint mb-2">Prices belong to sizes, not the item itself. Add every size that customers can book.</p><div id="item-size-rows"><div class="row g-2 item-size-row mb-2"><div class="col-md-6"><input class="form-control" name="size_name[]" placeholder="Size name (e.g. Small)" required></div><div class="col-md-6"><input class="form-control" name="size_price[]" type="number" min="0" step="0.01" placeholder="Price" required></div><div class="col-12"><input class="form-control" name="size_dimensions[]" placeholder="Dimensions (optional)"></div></div></div></div><?php endif ?>
<div class="col-12"><div class="form-check form-switch"><input type="hidden" name="is_active" value="0"><input class="form-check-input" id="is_active" name="is_active" type="checkbox" value="1"<?= old('is_active', (string) ($item['is_active'] ?? '1')) === '1' ? ' checked' : '' ?>><label class="form-check-label" for="is_active">Active and available when adding booking items</label></div></div>
</div><div class="form-actions"><a class="btn btn-light" href="<?= site_url('admin/items') ?>">Cancel</a><button class="btn btn-primary" type="submit"><?= $editing ? 'Save item' : 'Create item and sizes' ?></button></div></form></section>
