<?php if (! $editing): ?><?= $this->section('scripts') ?><script>document.addEventListener('click',function(e){if(!e.target.closest('[data-add-size-row]'))return;const row=document.querySelector('.item-size-row');if(!row)return;const clone=row.cloneNode(true);clone.querySelectorAll('input').forEach(input=>{input.value='';});document.getElementById('item-size-rows').appendChild(clone);});</script><?= $this->endSection() ?><?php endif ?>
